<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="robots" content="noindex, nofollow, noarchive"><title>{{ $brand['name'] }} · Feedback</title><style>body{margin:0;background:#f6f7fb;font:16px system-ui;color:#172033}main{max-width:480px;margin:auto;min-height:100vh;background:#fff;padding:32px 24px}.logo{width:56px;height:56px;border-radius:16px;object-fit:cover}h1{color:{{ $brand['primary_color'] }}}button,a{background:{{ $brand['primary_color'] }};color:#fff;border:0;border-radius:10px;padding:12px 16px;text-decoration:none}fieldset{border:0;padding:0;display:flex;gap:8px}label{font-size:24px}textarea{width:100%;min-height:100px;margin:16px 0;padding:10px}small{color:#667085}</style></head><body><main>@if($brand['logo_url'])<img class="logo" src="{{ $brand['logo_url'] }}" alt="{{ $brand['name'] }} logo">@endif<h1>{{ $brand['name'] }}</h1>@if($feedback->submitted_at)<p>Thank you for your feedback.</p>@if($reviewUrl)<p><a href="{{ $reviewUrl }}" rel="noopener noreferrer" target="_blank">Share a public review if you wish</a></p>@endif@else<form method="post"><input type="hidden" name="_token" value="{{ csrf_token() }}"><p>How was your experience?</p><fieldset>@for($i=1;$i<=5;$i++)<label><input required type="radio" name="rating" value="{{ $i }}">{{ $i }}</label>@endfor</fieldset><textarea name="comment" maxlength="2000" placeholder="Private feedback (optional)"></textarea><button type="submit">Submit feedback</button></form>@endif<small>Your feedback is shared privately with the restaurant.</small></main></body></html>
